'use strict';

const assert=require('assert');
const fs=require('fs');
const os=require('os');
const path=require('path');
const core=require('../../system-master/book-system/canonical-parent-v2-f6-core.js');
const rebind=require('../../system-master/book-system/export-freeze-v2.js');
const {ExportFreezeV2SqliteStore}=require('../../system-master/book-system/export-freeze-v2-sqlite-store.js');

const H=v=>core.sha256(String(v));
function clone(v){return JSON.parse(JSON.stringify(v));}
function expectCode(code,fn){assert.throws(fn,e=>e&&e.code===code,`expected ${code}`);}
function parentAt(status='FINALIZATION'){
  return core.sealParent({schema_version:core.SCHEMA_VERSION,state_version:9,state_digest:'0'.repeat(64),book_project:{book_project_id:'BOOK-PROJECT-001',book_id:'BOOK-001',status},governed_objects:{governing_briefs:[{object_id:'BRIEF-1',version:'1',book_project_id:'BOOK-PROJECT-001',object_digest:H('BRIEF-1:1')}],canon_manifests:[{object_id:'CANON-1',version:'1',book_project_id:'BOOK-PROJECT-001',object_digest:H('CANON-1:1')}],story_bibles:[{object_id:'BIBLE-1',version:'1',book_project_id:'BOOK-PROJECT-001',object_digest:H('BIBLE-1:1')}],book_plans:[{object_id:'PLAN-1',version:'1',book_project_id:'BOOK-PROJECT-001',object_digest:H('PLAN-1:1')}],manuscripts:[{object_id:'MS-1',version:'1',book_project_id:'BOOK-PROJECT-001',artifact_digest:H('MS-1:1:ARTIFACT')}]},research_evidence_links:[],author_decisions:[],integration_proposals:[],rights_custody_records:[],style_profiles:[{object_id:'STYLE-1',version:'1',book_project_id:'BOOK-PROJECT-001',standing:'CURRENT',profile_digest:H('STYLE-1:1:CURRENT')}],export_releases:[],active:{governing_brief_ref:'BRIEF-1:1',canon_manifest_ref:'CANON-1:1',story_bible_ref:'BIBLE-1:1',book_plan_ref:'PLAN-1:1',canonical_manuscript_ref:'MS-1:1',style_profile_ref:'STYLE-1:1'},authority_metadata:{owner:'SYSTEM_MASTER/BOOK',reconstruction:'B00-F9-QUALIFICATION-FIXTURE'},mutation_head:null});
}
function request(parent,state,overrides={}){
  const artifact=H('EXPORT-ARTIFACT-001');
  const base={freeze_request_id:'F9-FREEZE-001',idempotency_key:'F9-IDEM-001',authority_ref:'BOOK-EXPORT-FREEZE-AUTHORITY-REF-001',expected_parent_state_version:parent.state_version,expected_parent_state_digest:parent.state_digest,expected_export_freeze_identity:rebind.exportFreezeIdentity(state,parent),release_id:'RELEASE-F9-001',release_group_ref:'RELEASE-GROUP-F9-001',canonical_manuscript_identity:{manuscript_id:'MS-1',version_id:'1',artifact_digest:H('MS-1:1:ARTIFACT')},artifact_evidence:{artifact_ref:'ARTIFACT-EVIDENCE-F9-001',artifact_digest:artifact,artifact_currentness:'CURRENT_FOR_BOUND_SOURCE',format_identity:'PDF',source_manuscript_id:'MS-1',source_version_id:'1',source_digest:H('MS-1:1:ARTIFACT'),generator_or_toolchain_identity:'PORTABLE-FIXTURE-TOOLCHAIN'},target_medium_evidence:{target_medium_profile_id:'PRINT-PDF-PROFILE',target_medium_profile_version:'1',technical_state:'POST_LAYOUT_PROOF_COMPLETE',format_validation_result:'PASS',source_to_render_integrity_result:'PASS',accessibility_result:'NOT_APPLICABLE_WITH_RATIONALE',accessibility_rationale:'fixture medium declared not applicable',proof_result:'PASS',correction_ledger_ref:'CORRECTION-LEDGER-F9-001',correction_ledger_state:'CLOSED_CURRENT',rendered_candidate_digest:artifact},rights_privacy_evidence:{rights_state:'CURRENT_AUTHORIZED',privacy_state:'CURRENT_ALLOWED',evidence_ref:'RIGHTS-PRIVACY-FIXTURE-REF-001'},provenance_evidence:{currentness_state:'NONE',validation_result:'NOT_APPLICABLE',projection_ref:null,bound_artifact_digest:artifact},parent_admission_refs:[],author_decision_refs:[],created_at:'2026-09-12T07:41:00.000Z'};
  return Object.assign(base,overrides);
}
function temp(){const dir=fs.mkdtempSync(path.join(os.tmpdir(),'book-f9-'));return{dir,db:path.join(dir,'book.sqlite')}};
function seeded(parent,state,options={}){const x=temp(),store=new ExportFreezeV2SqliteStore(x.db,options);store.createParent(parent,'F9-CREATE');store.createExportFreezeState(state,'2026-09-12T07:40:30.000Z');return{...x,store};}
function cleanup(x){try{x.store.close();}catch(_){}try{fs.rmSync(x.dir,{recursive:true,force:true});}catch(_){}}
function count(s,t){return Number(s.db.prepare(`SELECT COUNT(*) AS n FROM ${t}`).get().n);}
const tests=[];function t(id,name,fn){tests.push({id,name,fn});}

t('Q065','export freeze is prepare-only until typed parent commit and never implies publication authorization',()=>{const p=parentAt(),s=rebind.createFreezeSpecialistState(p),r=request(p,s),pb=JSON.stringify(p),sb=JSON.stringify(s),prep=rebind.prepareExportFreezeRegistration({canonicalParent:p,exportFreezeState:s,request:r});assert.strictEqual(prep.parent_effect.effect_type,'REGISTER_EXPORT_RELEASE');assert.strictEqual(JSON.stringify(p),pb);assert.strictEqual(JSON.stringify(s),sb);assert.strictEqual(p.export_releases.length,0);assert.strictEqual(prep.parent_effect.effect_payload.record.publication_authorized,false);assert.strictEqual(prep.parent_effect.effect_payload.record.publication_authority_state,'NOT_AUTHORIZED');const x=seeded(p,s);try{const c=x.store.commitPreparedExportFreeze(prep);assert.strictEqual(c.parent_state.export_releases.length,1);assert.strictEqual(c.parent_state.export_releases[0].publication_authority_state,'NOT_AUTHORIZED');assert.strictEqual(c.parent_state.book_project.status,'FINALIZATION');assert.deepStrictEqual(c.parent_state.active,p.active);assert.strictEqual(count(x.store,'parent_commit_receipt'),1);assert.strictEqual(count(x.store,'book_export_freeze_receipt'),1);}finally{cleanup(x);}});

t('F9-PUBLICATION-REQUEST-FENCE','caller publication flag is rejected before parent effect',()=>{const p=parentAt(),s=rebind.createFreezeSpecialistState(p),r=request(p,s,{publication_authorized:true});expectCode('EXPORT_CANNOT_AUTHORIZE_PUBLICATION',()=>rebind.prepareExportFreezeRegistration({canonicalParent:p,exportFreezeState:s,request:r}));});

t('F9-STALE-PARENT','stale parent identity fails closed',()=>{const p=parentAt(),s=rebind.createFreezeSpecialistState(p),r=request(p,s,{expected_parent_state_digest:'f'.repeat(64)});expectCode('STALE_PARENT_WRITE',()=>rebind.prepareExportFreezeRegistration({canonicalParent:p,exportFreezeState:s,request:r}));});

t('F9-STALE-SPECIALIST','stale freeze specialist identity fails closed',()=>{const p=parentAt(),s=rebind.createFreezeSpecialistState(p),r=request(p,s,{expected_export_freeze_identity:'a'.repeat(64)});expectCode('EXPORT_FREEZE_IDENTITY_MISMATCH',()=>rebind.prepareExportFreezeRegistration({canonicalParent:p,exportFreezeState:s,request:r}));});

t('F9-SOURCE-MISMATCH','rendered artifact cannot bind wrong manuscript source digest',()=>{const p=parentAt(),s=rebind.createFreezeSpecialistState(p),r=request(p,s);r.artifact_evidence.source_digest='b'.repeat(64);expectCode('EXPORT_SOURCE_MANUSCRIPT_MISMATCH',()=>rebind.prepareExportFreezeRegistration({canonicalParent:p,exportFreezeState:s,request:r}));});

t('F9-NATIVE-NOT-INFERRED','unqualified format identity cannot be upgraded to native fidelity',()=>{const p=parentAt(),s=rebind.createFreezeSpecialistState(p),r=request(p,s);r.artifact_evidence.format_identity='NATIVE_OFFICE_FIDELITY';expectCode('UNSUPPORTED_OR_UNDECLARED_FORMAT_IDENTITY',()=>rebind.prepareExportFreezeRegistration({canonicalParent:p,exportFreezeState:s,request:r}));});

t('F9-RIGHTS-PRIVACY','rights/privacy boundary must be explicitly current and allowed',()=>{const p=parentAt(),s=rebind.createFreezeSpecialistState(p),r=request(p,s);r.rights_privacy_evidence.rights_state='UNKNOWN';expectCode('RIGHTS_PRIVACY_NOT_CURRENT_ALLOWED',()=>rebind.prepareExportFreezeRegistration({canonicalParent:p,exportFreezeState:s,request:r}));});

t('F9-PROOF','post-layout proof and integrity must pass independently',()=>{const p=parentAt(),s=rebind.createFreezeSpecialistState(p),r=request(p,s);r.target_medium_evidence.source_to_render_integrity_result='UNKNOWN';expectCode('SOURCE_TO_RENDER_INTEGRITY_NOT_PASS',()=>rebind.prepareExportFreezeRegistration({canonicalParent:p,exportFreezeState:s,request:r}));});

t('F9-ROLLBACK','specialist persistence failure rolls back canonical parent atomically',()=>{const p=parentAt(),s=rebind.createFreezeSpecialistState(p),prep=rebind.prepareExportFreezeRegistration({canonicalParent:p,exportFreezeState:s,request:request(p,s)}),x=seeded(p,s,{faultInjector:point=>{if(point==='after_export_freeze_update')throw new Error('INJECTED_FREEZE_FAILURE')}});try{expectCode('STORE_SQLITE_FAILURE',()=>x.store.commitPreparedExportFreeze(prep));assert.strictEqual(x.store.readCurrentParent('BOOK-PROJECT-001').export_releases.length,0);assert.strictEqual(count(x.store,'parent_commit_receipt'),0);}finally{cleanup(x);}});

t('F9-RESPONSE-LOSS','response loss reconciles one immutable release without duplicate commit',()=>{const p=parentAt(),s=rebind.createFreezeSpecialistState(p),prep=rebind.prepareExportFreezeRegistration({canonicalParent:p,exportFreezeState:s,request:request(p,s)}),x=seeded(p,s,{faultInjector:point=>{if(point==='after_commit')throw new Error('INJECTED_RESPONSE_LOSS')}});try{expectCode('STORE_SQLITE_FAILURE',()=>x.store.commitPreparedExportFreeze(prep));const rec=x.store.reconcileExportFreeze(prep);assert.strictEqual(rec.committed,true);assert.strictEqual(rec.parent_state.export_releases.length,1);const replay=x.store.commitPreparedExportFreeze(prep);assert.strictEqual(replay.replay,true);assert.strictEqual(count(x.store,'parent_commit_receipt'),1);assert.strictEqual(count(x.store,'book_export_freeze_receipt'),1);}finally{cleanup(x);}});

t('F9-RECOVERY','reopen recovery preserves freeze and parent receipt linkage',()=>{const p=parentAt(),s=rebind.createFreezeSpecialistState(p),prep=rebind.prepareExportFreezeRegistration({canonicalParent:p,exportFreezeState:s,request:request(p,s)}),x=temp();let store=new ExportFreezeV2SqliteStore(x.db);try{store.createParent(p,'F9-RECOVERY-CREATE');store.createExportFreezeState(s);const c=store.commitPreparedExportFreeze(prep),rid=c.specialist_receipt.receipt_id;store.close();store=new ExportFreezeV2SqliteStore(x.db);const recovered=store.recoverAndVerifyExportFreeze('BOOK-PROJECT-001');assert.strictEqual(recovered.export_freeze_receipt_count,1);assert.strictEqual(store.readExportFreezeReceipt(rid).publication_authority_state,'NOT_AUTHORIZED');assert.strictEqual(store.readCurrentParent('BOOK-PROJECT-001').export_releases.length,1);}finally{try{store.close();}catch(_){}try{fs.rmSync(x.dir,{recursive:true,force:true});}catch(_){}}});

let passed=0;for(const q of tests){try{q.fn();passed++;console.log(`PASS ${q.id} ${q.name}`);}catch(e){console.error(`FAIL ${q.id} ${q.name}`);console.error(e&&e.stack||e);process.exitCode=1;}}if(passed!==tests.length)process.exit(1);console.log(JSON.stringify({qualification_id:'BOOK-RECONSTRUCTION-B00-F9-EXPORT-FREEZE-REBIND-001',result_class:'PASS',case_count:tests.length,pass_count:passed,fail_count:0},null,2));
